use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn valid_indices_and_choices(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> bool {
    forall|i: int| 0 <= i < indices.len() ==> 
        (indices[i] as int) < choices.len() && 
        i < choices[indices[i] as int].len()
}

fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> (result: Vec<f64>)
    requires
        valid_indices_and_choices(indices, choices),
    ensures
        result.len() == indices.len(),
        forall|i: int| 0 <= i < indices.len() ==> 
            result[i] == choices[indices[i] as int][i],
{
    // Create a result vector with the same length as indices
    let mut result = Vec::with_capacity(indices.len());
    
    // Iterate through each position i
    let mut i: usize = 0;
    while i < indices.len()
        invariant
            0 <= i <= indices.len(),
            result.len() == i,
            forall|j: int| 0 <= j < i ==> 
                result[j] == choices[indices[j] as int][j],
            valid_indices_and_choices(indices, choices),
        decreases indices.len() - i,
    {
        let row_idx = indices[i];
        
        // Get the row using the index from indices array
        let row = &choices[row_idx as usize];
        
        // Get the element at column i from that row
        result.push(row[i]);
        
        i = i + 1;
    }
    
    result
}

}